draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '48px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1156', W / 2, H / 2);
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 60);
  ctx.lineTo(W / 2, H / 2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 20, H / 2 + 80);
  ctx.lineTo(W / 2 + 20, H / 2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 10, H / 2 + 80);
  ctx.lineTo(W / 2 - 10, H / 2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 10, H / 2 + 80);
  ctx.lineTo(W / 2 + 10, H / 2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 - 20, H / 2 + 90, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + 20, H / 2 + 90, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.rotate(Math.sin(t));
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 120);
  ctx.lineTo(W / 2, H / 2 + 150);
  ctx.stroke();
  ctx.restore();
}
